<script setup lang="ts">
import{ref,computed,onMounted,nextTick}from'vue'
import{X,FileText}from'lucide-vue-next'
import{recentFiles,libraryIndex,libraryRoot,refreshLibrary}from'../library'
import{t}from'../i18n'
const props=defineProps<{tabs:{id:string;label:string;path:string|null;handleKey?:string}[]}>(),emit=defineEmits<{close:[];open:[{path?:string;handleKey?:string;tabId?:string}];error:[unknown]}>(),query=ref(''),selected=ref(0),input=ref<HTMLInputElement>(),loading=ref(false)
const matches=computed(()=>{const list=[...props.tabs.map(tab=>({label:tab.label,path:tab.path||undefined,handleKey:tab.handleKey,tabId:tab.id,detail:t('已打开标签')})),...recentFiles.value.map(file=>({...file,label:file.path.split(/[\\/]/).pop()!,tabId:undefined,detail:file.path})),...libraryIndex.value.map(file=>({...file,label:file.name,tabId:undefined,detail:file.relative}))],seen=new Set<string>(),needle=query.value.toLocaleLowerCase();return list.filter(file=>{const key=file.path?.replace(/\\/g,'/').toLocaleLowerCase()||file.tabId!;if(seen.has(key))return false;seen.add(key);return(file.label+' '+file.detail+' '+(file.path||'')).toLocaleLowerCase().includes(needle)}).slice(0,200)})
function choose(index=selected.value){const file=matches.value[index];if(file)emit('open',file)}
function step(delta:number){selected.value=(selected.value+delta+Math.max(1,matches.value.length))%Math.max(1,matches.value.length);void nextTick(()=>document.querySelector('.quick-open [aria-selected=true]')?.scrollIntoView({block:'nearest'}))}
onMounted(async()=>{await nextTick();input.value?.focus();if(libraryRoot.value){loading.value=true;try{await refreshLibrary()}catch(e){emit('error',e)}finally{loading.value=false}}})
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="quick-open" role="dialog" aria-modal="true" :aria-label="t('快速打开')" @keydown.esc.stop="emit('close')" @keydown.down.prevent="step(1)" @keydown.up.prevent="step(-1)" @keydown.enter.prevent="choose()"><header><FileText :size="18"/><input ref="input" v-model="query" :aria-label="t('按文件名查找')" :placeholder="t('搜索文件名或最近文稿…')" @input="selected=0"><button class="icon-btn" :aria-label="t('关闭快速打开')" @click="emit('close')"><X :size="16"/></button></header><div class="quick-open-list" role="listbox" :aria-label="t('文稿列表')"><button v-for="(file,index) in matches" :key="file.path||file.tabId" role="option" :aria-selected="index===selected" @click="choose(index)"><strong>{{file.label}}</strong><small>{{file.detail}}</small></button><p v-if="!matches.length">{{t(loading?'正在读取文件…':'无匹配')}}</p></div><footer>{{t('↑↓ 选择 · Enter 打开 · Esc 关闭')}}</footer></section></div></template>
